":"https://s3-eu-west-1.amazonaws.com/agents-society-assets-files/pdf/c6951e60581a064e39eab9bf421882ef.pdf"},{"source":"cdg","source_ref":"128846","source_url":"https://www.cdgleisure.com/find-a-property/properties/128846-prime-fully-fitted-restaurant-kentish-town-road-london","status":"Available","source_updated_at":"2025-09-15T17:00:08+00:00","title":"Prime Fully Fitted Restaurant, Kentish Town Road","summary":"Prime Kentish Town Restaurant","address_line":"Kentish Town Road","area":null,"city":"London","postcode":"NW5","lat":51.55038894038751,"lng":-0.14061325396728552,"property_type":"Restaurant","use_class":"Class E","disposal_type":"lease_assignment","to_let":true,"for_sale":false,"rent_pa":null,"rent_raw":null,"rent_period":null,"premium":null,"premium_raw":null,"guide_price":null,"price_qualifier":"on_application","vat_applicable":true,"rateable_value":null,"business_rates":null,"service_charge":null,"estate_charge":null,"parking_charge":null,"tenure_raw":null,"lease_term_years":null,"lease_expiry":null,"rent_review_basis":null,"next_rent_review":null,"inside_1954_act":null,"size_sqft":1561,"size_sqm":145.02,"covers_internal":20,"covers_external":12,"floors":[{"name":"Ground","sqft":1028,"sqm":95.5},{"name":"Lower Ground","sqft":533,"sqm":49.52}],"licensing_notes":"The premises benefit from Class E planning use with a premises license allowing the sale of alcohol until midnight with standard restaurant conditions.","fit_out_state":"fully_fitted","epc_rating":null,"description":"The premises are currently fitted out as Café/Restaurant over the ground floor and basement. There is seating for approx. 30 persons on the ground floor main dining area with a further 20 covers in a private area to the rear. There is also alfresco dining on the front outside terrace for approx. 12 covers. The fully fitted kitchen is situated to the rear of the premises,  and there is a rear emergency exit/delivery access onto a service road.","location_description":"The property is located on Kentish Town Road in North West London, close to many independent and national operators, with heavy footfall day and night. Transport links are excellent with Kentish Town underground station being a short walk away.","key_features":["Prime High Street Location","High Footfall 24/7","Fully Fitted to a Good Standard","Outside Terrace Seating","Inside the L&T Act Lease","Excellent Transport Links"],"sections":[{"title":"Description","content":"The premises are currently fitted out as Café/Restaurant over the ground floor and basement. There is seating for approx. 30 persons on the ground floor main dining area with a further 20 covers in a private area to the rear. There is also alfresco dining on the front outside terrace for approx. 12 covers. The fully fitted kitchen is situated to the rear of the premises,  and there is a rear emergency exit/delivery access onto a service road."},{"title":"Terms","content":"An assignment of the existing lease expiring in December 2034, subject to 5 yearly rent reviews. The Lease is drawn inside the security of tenure provisions of the Landlord and Tenant Act 1954."},{"title":"Premium","content":"On Application."},{"title":"Rent","content":"The passing rent is £60,000 per annum exclusive."},{"title":"Planning/Licencing","content":"The premises benefit from Class E planning use with a premises license allowing the sale of alcohol until midnight with standard restaurant conditions."},{"title":"VAT","content":"All prices quoted may be subject to VAT if applicable."},{"title":"Holding Deposit","content":"A holding deposit will be required to secure the property; the deposit will buy a period of exclusivity and will be held in the CDG Leisure client account."},{"title":"Confidentiality","content":"This sale is highly confidential and under no circumstances should a direct approach be made to staff as they are unaware of an impending sale."}],"agent_name":"Salvatore Di Natale","agent_email":"salvatore@cdgleisure.com","agent_phone":"07989 471288","agent_photo":"https://as-images.imgix.net/0c80fd529148bd3060556967a6287ef8-salv%20pic%20for%20property%20details.jpg","images":[{"url":"https://as-images.imgix.net/8baa35ce07e2a64ba5d076d9b3ddcd7b-coffee-cups.jpg","alt":"Prime Fully Fitted Restaurant, Kentish Town Road, London, Restaurant Lease Assignment - coffee cups.jpg","source_url":"https://as-images.imgix.net/8baa35ce07e2a64ba5d076d9b3ddcd7b-coffee-cups.jpg?mark=https%3A%2F%2Fas-images.imgix.net%2F5fcc3b7220158f27f85989bfa2708db8-screenshot-2024-06-19-at-14-54-05-removebg-preview.png&mark-alpha=90&mark-scale=30&mark-align=right,bottom"}],"brochure_url":"https://s3-eu-west-1.amazonaws.com/agents-society-assets-files/pdf/7508c5b633da1ded5e2da5357aecdc05.pdf"}]$cdg$::jsonb;
begin
  select id into demo_agency from public.agencies where name = 'CDG demo' limit 1;
  if demo_agency is null then raise exception 'Demo agency "CDG demo" not found.'; end if;

  select array_agg(user_id order by user_id) into member_ids
    from public.agency_members where agency_id = demo_agency;
  if member_ids is null or array_length(member_ids, 1) = 0 then
    raise exception 'Demo agency has no members.';
  end if;

  for rec in select * from jsonb_array_elements(payload) loop
    i := i + 1;
    select p.id into lead
      from public.profiles p
      join public.agency_members am on am.user_id = p.id
     where am.agency_id = demo_agency and p.full_name = rec->>'agent_name'
     limit 1;
    if lead is null then lead := member_ids[1 + (i % array_length(member_ids, 1))]; end if;
    insert into public.disposals (
      agency_id, source, source_ref, source_url, status, source_updated_at,
      title, summary, address_line, area, city, postcode, lat, lng,
      property_type, use_class, disposal_type, to_let, for_sale,
      rent_pa, rent_raw, rent_period, premium, premium_raw, guide_price, price_qualifier,
      vat_applicable, rateable_value, business_rates, service_charge, estate_charge, parking_charge,
      tenure_raw, lease_term_years, lease_expiry, rent_review_basis, next_rent_review, inside_1954_act,
      size_sqft, size_sqm, covers_internal, covers_external, floors,
      licensing_notes, fit_out_state, epc_rating,
      description, location_description, key_features, sections,
      agent_name, agent_email, agent_phone, agent_photo,
      images, brochure_url,
      lead_agent_id, created_by
    ) values (
      demo_agency,
      coalesce(rec->>'source', 'cdg'), rec->>'source_ref', rec->>'source_url', rec->>'status',
      (rec->>'source_updated_at')::timestamptz,
      rec->>'title', rec->>'summary', rec->>'address_line', rec->>'area', rec->>'city',
      rec->>'postcode', (rec->>'lat')::double precision, (rec->>'lng')::double precision,
      rec->>'property_type', rec->>'use_class', rec->>'disposal_type',
      (rec->>'to_let')::boolean, (rec->>'for_sale')::boolean,
      (rec->>'rent_pa')::numeric, rec->>'rent_raw', rec->>'rent_period',
      (rec->>'premium')::numeric, rec->>'premium_raw', (rec->>'guide_price')::numeric,
      rec->>'price_qualifier',
      (rec->>'vat_applicable')::boolean, (rec->>'rateable_value')::numeric,
      (rec->>'business_rates')::numeric, (rec->>'service_charge')::numeric,
      (rec->>'estate_charge')::numeric, (rec->>'parking_charge')::numeric,
      rec->>'tenure_raw', (rec->>'lease_term_years')::int, (rec->>'lease_expiry')::date,
      rec->>'rent_review_basis', (rec->>'next_rent_review')::int, (rec->>'inside_1954_act')::boolean,
      (rec->>'size_sqft')::numeric, (rec->>'size_sqm')::numeric,
      (rec->>'covers_internal')::int, (rec->>'covers_external')::int,
      coalesce(rec->'floors', '[]'::jsonb),
      rec->>'licensing_notes', rec->>'fit_out_state', rec->>'epc_rating',
      rec->>'description', rec->>'location_description',
      coalesce(array(select jsonb_array_elements_text(rec->'key_features')), '{}'::text[]),
      coalesce(rec->'sections', '[]'::jsonb),
      rec->>'agent_name', rec->>'agent_email', rec->>'agent_phone', rec->>'agent_photo',
      coalesce(rec->'images', '[]'::jsonb), rec->>'brochure_url',
      lead, lead
    );
  end loop;
end $$;
